CREATE OR REPLACE FUNCTION public.consult_template_ids(_tenant uuid,_treatment uuid) RETURNS uuid[] LANGUAGE sql STABLE SET search_path=public AS $$ SELECT coalesce(array_agg(v.id ORDER BY v.id),'{}'::uuid[]) FROM public.dossier_template_versions v JOIN public.dossier_templates d ON d.id=v.template_id AND d.tenant_id=v.tenant_id JOIN public.treatments t ON t.id=_treatment AND t.tenant_id=_tenant WHERE v.tenant_id=_tenant AND v.status='live' AND ((t.dossier_template_override IS NOT NULL AND d.id=t.dossier_template_override) OR (t.dossier_template_override IS NULL AND d.category_id IN (SELECT l.category_id FROM public.treatment_category_links l WHERE l.tenant_id=_tenant AND l.treatment_id=_treatment UNION SELECT c.parent_id FROM public.treatment_category_links l JOIN public.treatment_categories c ON c.id=l.category_id AND c.tenant_id=l.tenant_id WHERE l.tenant_id=_tenant AND l.treatment_id=_treatment))); $$;
REVOKE ALL ON FUNCTION public.consult_template_ids(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.consult_template_ids(uuid,uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.freeze_consult_template_selection() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE tid uuid; BEGIN IF TG_OP='UPDATE' AND cardinality(OLD.template_version_ids)>0 THEN IF NEW.template_version_ids IS DISTINCT FROM OLD.template_version_ids THEN RAISE EXCEPTION 'De consultversie is vastgezet'; END IF; RETURN NEW; END IF; IF NEW.appointment_id IS NOT NULL AND cardinality(NEW.template_version_ids)=0 THEN SELECT treatment_id INTO tid FROM public.appointments WHERE id=NEW.appointment_id AND tenant_id=NEW.tenant_id; NEW.template_version_ids:=public.consult_template_ids(NEW.tenant_id,tid); END IF; RETURN NEW; END; $$;
CREATE TRIGGER consult_template_selection BEFORE INSERT OR UPDATE ON public.consult_notes FOR EACH ROW EXECUTE FUNCTION public.freeze_consult_template_selection();
UPDATE public.consult_notes n SET template_version_ids=public.consult_template_ids(n.tenant_id,a.treatment_id) FROM public.appointments a WHERE a.id=n.appointment_id AND a.tenant_id=n.tenant_id AND cardinality(n.template_version_ids)=0 AND n.status IN ('draft','parked');